## `config.ts`

```ts
import * as pulumi from "@pulumi/pulumi";

const cfg = new pulumi.Config("app-platform");

export type EnvName = "dev" | "prod";

export interface EnvSettings {
    env: EnvName;
    isProd: boolean;
    dbInstanceClass: string;
    dbMultiAz: boolean;
    dbAllocatedStorage: number;
    backupRetentionDays: number;
    replicaRegion: string;          // "" disables replication
    oidcProviderArn: string;
    serviceAccount: string;         // "namespace:name"
    dbPassword: pulumi.Output<string>;
}

export function loadEnv(): EnvSettings {
    const env = cfg.require<EnvName>("env");
    if (env !== "dev" && env !== "prod") {
        throw new Error(`app-platform:env must be "dev" or "prod", got "${env}"`);
    }
    const retention = cfg.requireNumber("backupRetentionDays");
    if (retention < 7) {
        throw new Error(`backupRetentionDays must be >= 7 (acceptance criteria), got ${retention}`);
    }
    return {
        env,
        isProd: env === "prod",
        dbInstanceClass: cfg.require("dbInstanceClass"),
        dbMultiAz: cfg.requireBoolean("dbMultiAz"),
        dbAllocatedStorage: cfg.requireNumber("dbAllocatedStorage"),
        backupRetentionDays: retention,
        replicaRegion: cfg.get("replicaRegion") ?? "",
        oidcProviderArn: cfg.require("oidcProviderArn"),
        serviceAccount: cfg.require("serviceAccount"),
        dbPassword: cfg.requireSecret("dbPassword"),
    };
}
```

