## `components/appPlatform.ts`

```ts
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";
import * as random from "@pulumi/random";

export interface AppPlatformArgs {
    /** Logical environment name; drives sizing and hardening defaults. */
    env: "dev" | "prod";

    // --- networking ---
    vpcId: pulumi.Input<string>;
    /** Private subnets for the RDS subnet group (>= 2 AZs). */
    dbSubnetIds: pulumi.Input<string>[];
    /** CIDRs allowed to reach Postgres on 5432 (e.g. node group subnets). */
    dbIngressCidrs: pulumi.Input<string>[];

    // --- database ---
    dbName: pulumi.Input<string>;
    dbUsername: pulumi.Input<string>;
    dbPassword: pulumi.Input<string>;   // pass a pulumi secret
    dbInstanceClass: pulumi.Input<string>;
    dbAllocatedStorage: pulumi.Input<number>;
    dbMultiAz: pulumi.Input<boolean>;
    backupRetentionDays: pulumi.Input<number>;

    // --- bucket ---
    /** Non-empty enables cross-region replication (prod). */
    replicaRegion?: string;

    // --- iam ---
    /** OIDC provider ARN of the EKS cluster (IRSA trust). */
    oidcProviderArn: pulumi.Input<string>;
    /** "namespace:serviceaccountname" */
    serviceAccount: string;

    tags?: Record<string, string>;
}

export class AppPlatform extends pulumi.ComponentResource {
    public readonly bucketName: pulumi.Output<string>;
    public readonly bucketArn: pulumi.Output<string>;
    public readonly dbEndpoint: pulumi.Output<string>;
    public readonly dbPort: pulumi.Output<number>;
    public readonly roleArn: pulumi.Output<string>;
    public readonly connectionStringSecretArn: pulumi.Output<string>;
    /** Secret — surfaces encrypted in state, redacted in CLI output. */
    public readonly connectionString: pulumi.Output<string>;

    constructor(name: string, args: AppPlatformArgs, opts?: pulumi.ComponentResourceOptions) {
        super("knr:infra:AppPlatform", name, {}, opts);

        const isProd = args.env === "prod";
        const parent = { parent: this };
        const tags = { ...(args.tags ?? {}), Environment: args.env, ManagedBy: "pulumi", Component: name };

        // ------------------------------------------------------------------
        // 1. S3 bucket: versioned, encrypted, private
        // ------------------------------------------------------------------
        const suffix = new random.RandomId(`${name}-suffix`, { byteLength: 4 }, parent);

        const bucket = new aws.s3.BucketV2(`${name}-assets`, {
            bucket: pulumi.interpolate`${name}-${args.env}-assets-${suffix.hex}`,
            forceDestroy: !isProd,
            tags,
        }, { ...parent, protect: isProd });

        new aws.s3.BucketVersioningV2(`${name}-assets-versioning`, {
            bucket: bucket.id,
            versioningConfiguration: { status: "Enabled" },
        }, parent);

        const kmsKey = isProd
            ? new aws.kms.Key(`${name}-s3-key`, {
                description: `${name} ${args.env} S3 CMK`,
                enableKeyRotation: true,
                deletionWindowInDays: 30,
                tags,
            }, parent)
            : undefined;

        new aws.s3.BucketServerSideEncryptionConfigurationV2(`${name}-assets-sse`, {
            bucket: bucket.id,
            rules: [{
                applyServerSideEncryptionByDefault: kmsKey
                    ? { sseAlgorithm: "aws:kms", kmsMasterKeyId: kmsKey.arn }
                    : { sseAlgorithm: "AES256" },
                bucketKeyEnabled: true,
            }],
        }, parent);

        new aws.s3.BucketPublicAccessBlock(`${name}-assets-pab`, {
            bucket: bucket.id,
            blockPublicAcls: true,
            blockPublicPolicy: true,
            ignorePublicAcls: true,
            restrictPublicBuckets: true,
        }, parent);

        new aws.s3.BucketOwnershipControls(`${name}-assets-ownership`, {
            bucket: bucket.id,
            rule: { objectOwnership: "BucketOwnerEnforced" },
        }, parent);

        // Deny any non-TLS access.
        new aws.s3.BucketPolicy(`${name}-assets-policy`, {
            bucket: bucket.id,
            policy: bucket.arn.apply(arn => JSON.stringify({
                Version: "2012-10-17",
                Statement: [{
                    Sid: "DenyInsecureTransport",
                    Effect: "Deny",
                    Principal: "*",
                    Action: "s3:*",
                    Resource: [arn, `${arn}/*`],
                    Condition: { Bool: { "aws:SecureTransport": "false" } },
                }],
            })),
        }, parent);

        // -------- cross-region replication (prod only) --------
        if (args.replicaRegion) {
            const replicaProvider = new aws.Provider(`${name}-replica-provider`, {
                region: args.replicaRegion as aws.Region,
            }, parent);

            const replicaBucket = new aws.s3.BucketV2(`${name}-assets-replica`, {
                bucket: pulumi.interpolate`${name}-${args.env}-assets-${suffix.hex}-replica`,
                tags: { ...tags, Role: "replica" },
            }, { parent: this, provider: replicaProvider, protect: true });

            new aws.s3.BucketVersioningV2(`${name}-assets-replica-versioning`, {
                bucket: replicaBucket.id,
                versioningConfiguration: { status: "Enabled" },
            }, { parent: this, provider: replicaProvider });

            new aws.s3.BucketServerSideEncryptionConfigurationV2(`${name}-assets-replica-sse`, {
                bucket: replicaBucket.id,
                rules: [{
                    applyServerSideEncryptionByDefault: { sseAlgorithm: "AES256" },
                    bucketKeyEnabled: true,
                }],
            }, { parent: this, provider: replicaProvider });

            new aws.s3.BucketPublicAccessBlock(`${name}-assets-replica-pab`, {
                bucket: replicaBucket.id,
                blockPublicAcls: true,
                blockPublicPolicy: true,
                ignorePublicAcls: true,
                restrictPublicBuckets: true,
            }, { parent: this, provider: replicaProvider });

            const replicationRole = new aws.iam.Role(`${name}-replication-role`, {
                assumeRolePolicy: JSON.stringify({
                    Version: "2012-10-17",
                    Statement: [{
                        Effect: "Allow",
                        Principal: { Service: "s3.amazonaws.com" },
                        Action: "sts:AssumeRole",
                    }],
                }),
                tags,
            }, parent);

            new aws.iam.RolePolicy(`${name}-replication-policy`, {
                role: replicationRole.id,
                policy: pulumi.all([bucket.arn, replicaBucket.arn, kmsKey?.arn ?? pulumi.output(undefined)])
                    .apply(([src, dst, keyArn]) => JSON.stringify({
                        Version: "2012-10-17",
                        Statement: [
                            {
                                Effect: "Allow",
                                Action: ["s3:GetReplicationConfiguration", "s3:ListBucket"],
                                Resource: src,
                            },
                            {
                                Effect: "Allow",
                                Action: [
                                    "s3:GetObjectVersionForReplication",
                                    "s3:GetObjectVersionAcl",
                                    "s3:GetObjectVersionTagging",
                                ],
                                Resource: `${src}/*`,
                            },
                            {
                                Effect: "Allow",
                                Action: [
                                    "s3:ReplicateObject",
                                    "s3:ReplicateDelete",
                                    "s3:ReplicateTags",
                                ],
                                Resource: `${dst}/*`,
                            },
                            ...(keyArn ? [{
                                Effect: "Allow",
                                Action: ["kms:Decrypt"],
                                Resource: keyArn,
                            }] : []),
                        ],
                    })),
            }, parent);

            new aws.s3.BucketReplicationConfig(`${name}-assets-replication`, {
                role: replicationRole.arn,
                bucket: bucket.id,
                rules: [{
                    id: "replicate-all",
                    status: "Enabled",
                    priority: 1,
                    filter: {},
                    deleteMarkerReplication: { status: "Enabled" },
                    destination: {
                        bucket: replicaBucket.arn,
                        storageClass: "STANDARD_IA",
                    },
                }],
            }, parent);
        }

        // ------------------------------------------------------------------
        // 2. RDS PostgreSQL
        // ------------------------------------------------------------------
        const subnetGroup = new aws.rds.SubnetGroup(`${name}-db-subnets`, {
            subnetIds: args.dbSubnetIds,
            tags,
        }, parent);

        const dbSg = new aws.ec2.SecurityGroup(`${name}-db-sg`, {
            vpcId: args.vpcId,
            description: `${name} ${args.env} postgres access`,
            ingress: [{
                protocol: "tcp",
                fromPort: 5432,
                toPort: 5432,
                cidrBlocks: args.dbIngressCidrs,
                description: "Postgres from cluster subnets",
            }],
            egress: [{ protocol: "-1", fromPort: 0, toPort: 0, cidrBlocks: ["0.0.0.0/0"] }],
            tags,
        }, parent);

        const dbKey = isProd
            ? new aws.kms.Key(`${name}-rds-key`, {
                description: `${name} ${args.env} RDS CMK`,
                enableKeyRotation: true,
                deletionWindowInDays: 30,
                tags,
            }, parent)
            : undefined;

        const db = new aws.rds.Instance(`${name}-db`, {
            identifier: `${name}-${args.env}`,
            engine: "postgres",
            engineVersion: "16.3",
            instanceClass: args.dbInstanceClass,
            allocatedStorage: args.dbAllocatedStorage,
            maxAllocatedStorage: isProd ? 1000 : 100,
            storageType: "gp3",
            dbName: args.dbName,
            username: args.dbUsername,
            password: args.dbPassword,
            dbSubnetGroupName: subnetGroup.name,
            vpcSecurityGroupIds: [dbSg.id],

            // --- acceptance criteria ---
            publiclyAccessible: false,
            deletionProtection: true,
            backupRetentionPeriod: args.backupRetentionDays,
            storageEncrypted: true,
            kmsKeyId: dbKey?.arn,

            multiAz: args.dbMultiAz,
            backupWindow: "03:00-04:00",
            maintenanceWindow: "sun:04:30-sun:05:30",
            autoMinorVersionUpgrade: true,
            copyTagsToSnapshot: true,
            performanceInsightsEnabled: isProd,
            enabledCloudwatchLogsExports: ["postgresql", "upgrade"],
            skipFinalSnapshot: false,
            finalSnapshotIdentifier: `${name}-${args.env}-final-${Date.now()}`,
            applyImmediately: !isProd,
            tags,
        }, { ...parent, protect: isProd });

        // ------------------------------------------------------------------
        // 3. IAM role for the Kubernetes service account (IRSA)
        // ------------------------------------------------------------------
        const [saNamespace, saName] = args.serviceAccount.split(":");
        if (!saNamespace || !saName) {
            throw new Error(`serviceAccount must be "namespace:name", got "${args.serviceAccount}"`);
        }

        const oidcHost = pulumi.output(args.oidcProviderArn)
            .apply(arn => arn.split("/").slice(1).join("/"));

        const role = new aws.iam.Role(`${name}-sa-role`, {
            assumeRolePolicy: pulumi.all([args.oidcProviderArn, oidcHost])
                .apply(([providerArn, host]) => JSON.stringify({
                    Version: "2012-10-17",
                    Statement: [{
                        Effect: "Allow",
                        Principal: { Federated: providerArn },
                        Action: "sts:AssumeRoleWithWebIdentity",
                        Condition: {
                            StringEquals: {
                                [`${host}:aud`]: "sts.amazonaws.com",
                                [`${host}:sub`]: `system:serviceaccount:${saNamespace}:${saName}`,
                            },
                        },
                    }],
                })),
            maxSessionDuration: 3600,
            tags,
        }, parent);

        // Least privilege: explicit actions, resource-scoped. No wildcards on actions.
        new aws.iam.RolePolicy(`${name}-sa-policy`, {
            role: role.id,
            policy: pulumi.all([bucket.arn, kmsKey?.arn ?? pulumi.output(undefined)])
                .apply(([bucketArn, keyArn]) => JSON.stringify({
                    Version: "2012-10-17",
                    Statement: [
                        {
                            Sid: "ListAssets",
                            Effect: "Allow",
                            Action: ["s3:ListBucket", "s3:GetBucketLocation"],
                            Resource: bucketArn,
                        },
                        {
                            Sid: "ReadWriteAssets",
                            Effect: "Allow",
                            Action: ["s3:GetObject", "s3:PutObject", "s3:DeleteObject", "s3:AbortMultipartUpload"],
                            Resource: `${bucketArn}/*`,
                        },
                        ...(keyArn ? [{
                            Sid: "UseBucketCmk",
                            Effect: "Allow",
                            Action: ["kms:Decrypt", "kms:GenerateDataKey"],
                            Resource: keyArn,
                        }] : []),
                    ],
                })),
        }, parent);

        // ------------------------------------------------------------------
        // 4. Connection string -> Secrets Manager (never plaintext in Git)
        // ------------------------------------------------------------------
        const connectionString = pulumi
            .all([args.dbUsername, args.dbPassword, db.address, db.port, args.dbName])
            .apply(([u, p, host, port, name_]) =>
                `postgresql://${u}:${encodeURIComponent(p)}@${host}:${port}/${name_}?sslmode=require`)
            .apply(s => pulumi.secret(s));

        const secret = new aws.secretsmanager.Secret(`${name}-db-url`, {
            name: `${name}/${args.env}/db-connection-string`,
            description: "Postgres connection string",
            kmsKeyId: dbKey?.arn,
            recoveryWindowInDays: isProd ? 30 : 0,
            tags,
        }, parent);

        new aws.secretsmanager.SecretVersion(`${name}-db-url-v`, {
            secretId: secret.id,
            secretString: connectionString,
        }, parent);

        new aws.iam.RolePolicy(`${name}-sa-secret-policy`, {
            role: role.id,
            policy: secret.arn.apply(arn => JSON.stringify({
                Version: "2012-10-17",
                Statement: [{
                    Effect: "Allow",
                    Action: ["secretsmanager:GetSecretValue"],
                    Resource: arn,
                }],
            })),
        }, parent);

        this.bucketName = bucket.bucket;
        this.bucketArn = bucket.arn;
        this.dbEndpoint = db.endpoint;
        this.dbPort = db.port;
        this.roleArn = role.arn;
        this.connectionStringSecretArn = secret.arn;
        this.connectionString = connectionString;

        this.registerOutputs({
            bucketName: this.bucketName,
            dbEndpoint: this.dbEndpoint,
            roleArn: this.roleArn,
            connectionStringSecretArn: this.connectionStringSecretArn,
        });
    }
}
