## `index.ts`

```ts
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";
import { AppPlatform } from "./components/appPlatform";
import { loadEnv } from "./config";

const env = loadEnv();

const vpc = aws.ec2.getVpcOutput({ default: true });
const subnets = aws.ec2.getSubnetsOutput({
    filters: [{ name: "vpc-id", values: [vpc.id] }],
});

const platform = new AppPlatform("webapp", {
    env: env.env,
    vpcId: vpc.id,
    dbSubnetIds: [subnets.ids[0], subnets.ids[1]],
    dbIngressCidrs: [vpc.cidrBlock],

    dbName: "webapp",
    dbUsername: "webapp",
    dbPassword: env.dbPassword,
    dbInstanceClass: env.dbInstanceClass,
    dbAllocatedStorage: env.dbAllocatedStorage,
    dbMultiAz: env.dbMultiAz,
    backupRetentionDays: env.backupRetentionDays,

    replicaRegion: env.replicaRegion,

    oidcProviderArn: env.oidcProviderArn,
    serviceAccount: env.serviceAccount,

    tags: { Project: "webapp" },
});

export const bucketName = platform.bucketName;
export const dbEndpoint = platform.dbEndpoint;
export const serviceRoleArn = platform.roleArn;
export const dbSecretArn = platform.connectionStringSecretArn;
```

